$Result = [PSCustomObject]@{
    ComputerName = $env:COMPUTERNAME
    BitLocker    = "Unknown"
    TPM          = "Unknown"
    Antivirus    = "Unknown"
}

$BL = Get-BitLockerVolume -MountPoint C:

if ($BL.ProtectionStatus -eq "On")
{
    $Result.BitLocker = "Compliant"
}
else
{
    $Result.BitLocker = "Non-Compliant"
}

$TPM = Get-Tpm

if ($TPM.TpmReady)
{
    $Result.TPM = "Available"
}
else
{
    $Result.TPM = "Not Ready"
}

$AV = Get-CimInstance `
    -Namespace root/SecurityCenter2 `
    -Class AntiVirusProduct

if ($AV)
{
    $Result.Antivirus = "Installed"
}

$Result | Format-Table -AutoSize
